// ═══ تجهيز الطلب ═══
// الفرع بيتحوّل لاسم المخزن في eplus، والطلب بيتبعت للوسيط اللي
// بيختار سيرفر الفرع نفسه (مش سيرفر المعمورة لكل الفروع زي قبل كده).

const q      = $('Webhook').first().json.query || {};
const code   = String(q.code   ?? '').trim();
const branch = String(q.branch ?? '').trim();

// نفس aliases في جدول branches — لو ضفت فرع جديد ضيفه هنا كمان
const STORE = {
  'المعمورة':    'الصيدلية',
  'سان ستيفانو': 'ابراهيم حمدي 2',
  'سيدى بشر':    'ابراهيم حمدي 3',
  'سيدي بشر':    'ابراهيم حمدي 3'
};

// ⚠️ الرد القديم كان بيرجّع balance:0 من غير أي خطأ لو الفرع غلط أو ناقص،
//    فالشاشة كانت بتعرض صفر كأنه رصيد حقيقي. دلوقتي بيرجّع سبب واضح.
const fail = (error, extra) => [{ json: Object.assign(
  { found: false, in_branch: false, balance: 0, itm_name_ar: '', ok: false, error },
  extra || {}
) }];

if (!code)   return fail('الكود ناقص');
if (!branch) return fail('الفرع ناقص — الشاشة مابعتتش فرع');
if (!STORE[branch]) return fail('فرع غير معروف: ' + branch, { known: Object.keys(STORE) });

return [{ json: {
  ok: true,
  code,
  branch,
  store: STORE[branch],
  proxy: {
    branch: branch,                 // ← الوسيط بيختار base + بيانات دخول الفرع ده
    method: 'PATCH',
    path: '/api/Item/SearchItem',
    params: [{ key: 'itm_code_search', value: code, enabled: true }],
    preview: false                  // من غيرها بترجّع 50 صف بس
  }
} }];

// ═══ تجميع الرصيد ═══
const prep = $('تجهيز الطلب').first().json;
const res  = $input.first().json;   // رد eplus_proxy

const fail = (error, extra) => [{ json: Object.assign(
  { found: false, in_branch: false, balance: 0, itm_name_ar: '', error },
  extra || {}
) }];

if (res && res.ok === false) {
  // الوسيط بيرجّع branch_not_configured لو الفرع مش في EPLUS_BRANCHES
  return fail('تعذّر الوصول لسيرفر الفرع: ' + (res.error || res.status || 'سبب غير معروف'),
              { configured: res.configured || null });
}

let data = [];
try {
  const parsed = typeof res.output === 'string' ? JSON.parse(res.output) : (res.output || {});
  data = Array.isArray(parsed.Data) ? parsed.Data : [];
} catch (e) {
  return fail('رد غير مفهوم من eplus');
}

// المطابقة على الكود أو الباركود الداخلي
const same = data.filter(i =>
  String(i.itm_code  ?? '').trim() === prep.code ||
  String(i.itnl_code ?? '').trim() === prep.code
);
const mine = same.find(i => String(i.sto_name ?? '').trim() === prep.store);
const any  = same[0];

return [{ json: {
  // نفس الحقول القديمة عشان الشاشة ماتقعش قبل ما نحدّثها
  found:       !!any,                       // الكود موجود في eplus (مش شرط في فرعك)
  itm_name_ar: (mine || any)?.itm_name_ar || '',
  balance:     mine ? (Number(mine.sto_qty_big) || 0) : 0,
  in_branch:   !!mine,                      // ← دي الإشارة الصح: الصنف في مخزون فرعك

  // حقول تشخيص جديدة
  branch:       prep.branch,
  store:        prep.store,
  stores_found: [...new Set(same.map(i => String(i.sto_name ?? '').trim()).filter(Boolean))],
  source_url:   res.url || null,            // بيثبت إنك ضربت سيرفر الفرع الصح
  took_ms:      res.time_ms ?? null
} }];
